"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[13170],{80576(e,o,a){a.r(o),a.d(o,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>i,metadata:()=>s,toc:()=>l});const s=JSON.parse('{"id":"cursos/docker/modulos/seguridad-docker/cuestionario","title":"Cuestionario M13 \u2014 Seguridad en Docker","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/13-seguridad-docker/cuestionario.md","sourceDirName":"cursos/docker/modulos/13-seguridad-docker","slug":"/cursos/docker/modulos/seguridad-docker/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/seguridad-docker/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/seguridad-docker/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/seguridad-docker/ejercicio"}}');var n=a(74848),r=a(28453);const i={sidebar_label:"Cuestionario"},c="Cuestionario M13 \u2014 Seguridad en Docker",t={},l=[{value:"1. [Investigar] \xbfC\xf3mo funciona exactamente seccomp (Secure Computing Mode) y c\xf3mo Docker configura un perfil por defecto? \xbfQu\xe9 syscalls bloquea y por qu\xe9 esas espec\xedficamente?",id:"1-investigar-c\xf3mo-funciona-exactamente-seccomp-secure-computing-mode-y-c\xf3mo-docker-configura-un-perfil-por-defecto-qu\xe9-syscalls-bloquea-y-por-qu\xe9-esas-espec\xedficamente",level:3},{value:"2. [Investigar] \xbfQu\xe9 es Falco y c\xf3mo implementa detecci\xf3n de amenazas en tiempo real para contenedores usando eBPF? \xbfQu\xe9 tipo de comportamientos an\xf3malos puede detectar?",id:"2-investigar-qu\xe9-es-falco-y-c\xf3mo-implementa-detecci\xf3n-de-amenazas-en-tiempo-real-para-contenedores-usando-ebpf-qu\xe9-tipo-de-comportamientos-an\xf3malos-puede-detectar",level:3},{value:"3. [Investigar] \xbfQu\xe9 son exactamente los perfiles de AppArmor y SELinux y c\xf3mo Docker los usa? \xbfQu\xe9 diferencia hay entre ambos y cu\xe1l elegir\xedas para producci\xf3n?",id:"3-investigar-qu\xe9-son-exactamente-los-perfiles-de-apparmor-y-selinux-y-c\xf3mo-docker-los-usa-qu\xe9-diferencia-hay-entre-ambos-y-cu\xe1l-elegir\xedas-para-producci\xf3n",level:3},{value:"4. [Investigar] \xbfQu\xe9 es exactamente Docker Scout y c\xf3mo implementa el an\xe1lisis de &quot;supply chain&quot; m\xe1s all\xe1 del escaneo de vulnerabilidades? \xbfQu\xe9 diferencia hay con Trivy?",id:"4-investigar-qu\xe9-es-exactamente-docker-scout-y-c\xf3mo-implementa-el-an\xe1lisis-de-supply-chain-m\xe1s-all\xe1-del-escaneo-de-vulnerabilidades-qu\xe9-diferencia-hay-con-trivy",level:3},{value:"5. [Conectar] La clase menciona <code>--cap-drop ALL</code>. \xbfC\xf3mo se relacionan las capabilities con los user namespaces? \xbfUn contenedor que corre como root con capabilities restringidas es realmente seguro?",id:"5-conectar-la-clase-menciona---cap-drop-all-c\xf3mo-se-relacionan-las-capabilities-con-los-user-namespaces-un-contenedor-que-corre-como-root-con-capabilities-restringidas-es-realmente-seguro",level:3},{value:"6. [Conectar] \xbfQu\xe9 es exactamente Docker Content Trust (DCT) y c\xf3mo se relaciona con The Update Framework (TUF) y Notary? \xbfC\xf3mo protege contra ataques de supply chain?",id:"6-conectar-qu\xe9-es-exactamente-docker-content-trust-dct-y-c\xf3mo-se-relaciona-con-the-update-framework-tuf-y-notary-c\xf3mo-protege-contra-ataques-de-supply-chain",level:3},{value:"7. [Conectar] \xbfC\xf3mo funciona <code>docker run --read-only</code> y en qu\xe9 casos es aplicable? \xbfC\xf3mo manej\xe1s directorios que necesitan escritura (como <code>/tmp</code> o <code>/var/run</code>)?",id:"7-conectar-c\xf3mo-funciona-docker-run---read-only-y-en-qu\xe9-casos-es-aplicable-c\xf3mo-manej\xe1s-directorios-que-necesitan-escritura-como-tmp-o-varrun",level:3},{value:"8. [Cuestionar] &quot;Root en un contenedor es root en el host&quot;. \xbfEs esto cierto o un mito? \xbfQu\xe9 protecciones existen entre root del contenedor y root del host?",id:"8-cuestionar-root-en-un-contenedor-es-root-en-el-host-es-esto-cierto-o-un-mito-qu\xe9-protecciones-existen-entre-root-del-contenedor-y-root-del-host",level:3},{value:"9. [Cuestionar] \xbfEs <code>docker run --privileged</code> alguna vez aceptable en producci\xf3n? \xbfQu\xe9 casos de uso lo justifican y c\xf3mo mitig\xe1s el riesgo?",id:"9-cuestionar-es-docker-run---privileged-alguna-vez-aceptable-en-producci\xf3n-qu\xe9-casos-de-uso-lo-justifican-y-c\xf3mo-mitig\xe1s-el-riesgo",level:3},{value:"10. [Cuestionar] \xbfDeben las organizaciones adoptar &quot;zero trust&quot; en la red de contenedores (mTLS, NetworkPolicy) o es suficiente con firewalls perimetrales tradicionales?",id:"10-cuestionar-deben-las-organizaciones-adoptar-zero-trust-en-la-red-de-contenedores-mtls-networkpolicy-o-es-suficiente-con-firewalls-perimetrales-tradicionales",level:3}];function d(e){const o={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(o.header,{children:(0,n.jsx)(o.h1,{id:"cuestionario-m13--seguridad-en-docker",children:"Cuestionario M13 \u2014 Seguridad en Docker"})}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,n.jsx)(o.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsx)(o.h3,{id:"1-investigar-c\xf3mo-funciona-exactamente-seccomp-secure-computing-mode-y-c\xf3mo-docker-configura-un-perfil-por-defecto-qu\xe9-syscalls-bloquea-y-por-qu\xe9-esas-espec\xedficamente",children:"1. [Investigar] \xbfC\xf3mo funciona exactamente seccomp (Secure Computing Mode) y c\xf3mo Docker configura un perfil por defecto? \xbfQu\xe9 syscalls bloquea y por qu\xe9 esas espec\xedficamente?"}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": seccomp es una facility del kernel Linux que filtra syscalls mediante un BPF (Berkeley Packet Filter) program. Docker genera un perfil seccomp por defecto (archivo JSON, visible en moby/moby/profiles/seccomp/default.json) que aplica a todo contenedor nuevo. El perfil usa una whitelist: ~44 syscalls bloqueadas expl\xedcitamente (SCMP_ACT_ERRNO), ~300 permitidas (SCMP_ACT_ALLOW), y el resto por defecto permitido. Las syscalls bloqueadas incluyen: ",(0,n.jsx)(o.code,{children:"reboot"})," (reiniciar el host), ",(0,n.jsx)(o.code,{children:"kexec_load"})," (cargar nuevo kernel), ",(0,n.jsx)(o.code,{children:"mount"})," (montar filesystems, peligroso para breakout), ",(0,n.jsx)(o.code,{children:"ptrace"})," (inspeccionar procesos fuera del contenedor), ",(0,n.jsx)(o.code,{children:"personality"})," (cambiar personalidad del proceso), ",(0,n.jsx)(o.code,{children:"setdomainname"}),"/",(0,n.jsx)(o.code,{children:"sethostname"})," (cambiar identidad del host). Docker eligi\xf3 estas syscalls porque no son necesarias para el 99% de las aplicaciones y son vectores de ataque comunes (privilege escalation, container breakout)."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n del kernel (man 7 seccomp) y el perfil de Docker (github.com/moby/moby) documentan cada syscall bloqueada. El perfil usa ",(0,n.jsx)(o.code,{children:"SCMP_ACT_ERRNO"})," (devuelve error EPERM) en lugar de ",(0,n.jsx)(o.code,{children:"SCMP_ACT_KILL"})," (mata el proceso), porque matar un contenedor entero por una syscall no intencional es demasiado disruptivo. Administradores pueden generar perfiles personalizados con ",(0,n.jsx)(o.code,{children:"strace"})," (para capturar todas las syscalls que la app realmente usa) y crear un perfil whitelist restringido a solo esas. OCI runtime spec define c\xf3mo pasar perfiles seccomp en ",(0,n.jsx)(o.code,{children:"config.json"}),". Para m\xe1xima seguridad: perfil whitelist por aplicaci\xf3n (solo las syscalls necesarias, ~50-100 para una app t\xedpica, en lugar de ~300)."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsx)(o.h3,{id:"2-investigar-qu\xe9-es-falco-y-c\xf3mo-implementa-detecci\xf3n-de-amenazas-en-tiempo-real-para-contenedores-usando-ebpf-qu\xe9-tipo-de-comportamientos-an\xf3malos-puede-detectar",children:"2. [Investigar] \xbfQu\xe9 es Falco y c\xf3mo implementa detecci\xf3n de amenazas en tiempo real para contenedores usando eBPF? \xbfQu\xe9 tipo de comportamientos an\xf3malos puede detectar?"}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": Falco (Sysdig, proyecto CNCF graduado) es un runtime security tool que monitorea syscalls en tiempo real usando un m\xf3dulo de kernel o eBPF probe, y eval\xfaa reglas de comportamiento contra un stream de eventos. Detecta comportamientos an\xf3malos como: 1) Un contenedor nginx ejecutando un shell (",(0,n.jsx)(o.code,{children:"/bin/sh"}),", ",(0,n.jsx)(o.code,{children:"bash"}),") o descargando archivos (",(0,n.jsx)(o.code,{children:"curl"}),", ",(0,n.jsx)(o.code,{children:"wget"}),") \u2014 posible RCE, 2) Escritura en directorios de binarios (",(0,n.jsx)(o.code,{children:"/bin/"}),", ",(0,n.jsx)(o.code,{children:"/usr/bin/"}),"), 3) Acceso a archivos sensibles del host (",(0,n.jsx)(o.code,{children:"/etc/shadow"}),"), 4) Conexiones de red salientes a IPs sospechosas, 5) Montaje de filesystems desde dentro del contenedor, 6) Cambio de user namespace o capabilities, 7) Spawning de procesos inesperados (un contenedor de Redis ejecutando ",(0,n.jsx)(o.code,{children:"cron"}),"). Las reglas se definen en YAML (macros, lists, conditions) y se eval\xfaan en tiempo real."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": Falco fue creado por Loris Degioanni (Sysdig, ex-Wireshark) basado en la libsinsp que captura syscalls con overhead m\xednimo. La versi\xf3n con eBPF (Falco 0.20+) usa eBPF probes en lugar de un m\xf3dulo de kernel, eliminando la necesidad de compilar m\xf3dulos. Falco se integra con sistemas de alerta (Slack, PagerDuty, webhooks) y SIEMs (Splunk, Elasticsearch). Las reglas por defecto incluyen el CIS Benchmark y el MITRE ATT&CK framework para contenedores. Falco es parte del ecosistema de Cloud Native Runtime Security junto con Tracee (Aqua) y Tetragon (Isovalent). La filosof\xeda: los contenedores deben comportarse de manera predecible; cualquier desviaci\xf3n es sospechosa y merece alerta."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsx)(o.h3,{id:"3-investigar-qu\xe9-son-exactamente-los-perfiles-de-apparmor-y-selinux-y-c\xf3mo-docker-los-usa-qu\xe9-diferencia-hay-entre-ambos-y-cu\xe1l-elegir\xedas-para-producci\xf3n",children:"3. [Investigar] \xbfQu\xe9 son exactamente los perfiles de AppArmor y SELinux y c\xf3mo Docker los usa? \xbfQu\xe9 diferencia hay entre ambos y cu\xe1l elegir\xedas para producci\xf3n?"}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": AppArmor y SELinux son LSMs (Linux Security Modules) \u2014 sistemas de control de acceso obligatorio (MAC) integrados en el kernel. Docker puede aplicar perfiles a contenedores con ",(0,n.jsx)(o.code,{children:"--security-opt apparmor=&#x3C;profile>"})," o ",(0,n.jsx)(o.code,{children:"--security-opt label=type:&#x3C;selinux_type>"}),". AppArmor usa perfiles basados en paths: define qu\xe9 archivos, capabilities, y recursos puede acceder un proceso (ej. ",(0,n.jsx)(o.code,{children:"/usr/bin/nginx &#x7B; /var/www/** r, /etc/nginx/** r, ... &#x7D;"}),'). SELinux usa etiquetas (labels) en cada objeto (archivo, socket, proceso) y pol\xedticas que definen qu\xe9 transiciones entre labels son permitidas. AppArmor es m\xe1s simple (basado en paths, m\xe1s f\xe1cil de escribir perfiles). SELinux es m\xe1s granular y seguro (basado en labels, sigue el principio de "deny by default"). Docker incluye un perfil AppArmor por defecto (',(0,n.jsx)(o.code,{children:"docker-default"}),") que restringe capabilities y acceso a paths sensibles. Para producci\xf3n, SELinux es m\xe1s robusto pero m\xe1s complejo; AppArmor es m\xe1s accesible y todav\xeda muy efectivo."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": SELinux fue desarrollado por la NSA y Red Hat (RHEL lo habilita por defecto). AppArmor fue desarrollado por Immunix/Canonical (Ubuntu lo habilita por defecto). Docker genera autom\xe1ticamente un perfil AppArmor para cada contenedor basado en el perfil base ",(0,n.jsx)(o.code,{children:"docker-default"})," con las capabilities y paths que el contenedor necesita. Para SELinux, Docker asigna autom\xe1ticamente un label MCS (Multi-Category Security) \xfanico a cada contenedor, aislando contenedores entre s\xed (incluso si ambos corren como root). El CIS Docker Benchmark recomienda habilitar tanto AppArmor/SELinux como sea posible. La elecci\xf3n pr\xe1ctica: si tu SO es Ubuntu/Debian \u2192 AppArmor. Si es RHEL/CentOS/Fedora \u2192 SELinux."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsx)(o.h3,{id:"4-investigar-qu\xe9-es-exactamente-docker-scout-y-c\xf3mo-implementa-el-an\xe1lisis-de-supply-chain-m\xe1s-all\xe1-del-escaneo-de-vulnerabilidades-qu\xe9-diferencia-hay-con-trivy",children:'4. [Investigar] \xbfQu\xe9 es exactamente Docker Scout y c\xf3mo implementa el an\xe1lisis de "supply chain" m\xe1s all\xe1 del escaneo de vulnerabilidades? \xbfQu\xe9 diferencia hay con Trivy?'}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": Docker Scout (Docker Inc., 2022) es un servicio de an\xe1lisis de software supply chain integrado con Docker que va m\xe1s all\xe1 del escaneo de CVEs: 1) ",(0,n.jsx)(o.strong,{children:"SBOM generation"})," (lista completa de componentes), 2) ",(0,n.jsx)(o.strong,{children:"Remediation recommendations"})," (sugiere actualizaciones de imagen base que resuelven CVEs), 3) ",(0,n.jsx)(o.strong,{children:"Policy evaluation"}),' (define pol\xedticas como "no CRITICAL CVEs", "imagen base debe ser <30 d\xedas"), 4) ',(0,n.jsx)(o.strong,{children:"Dependency graph"})," (visualiza dependencias transitivas \u2014 qu\xe9 paquete introdujo la vulnerabilidad), 5) ",(0,n.jsx)(o.strong,{children:"Contextual analysis"})," (eval\xfaa si la vulnerabilidad es explotable en tu contexto de uso, no solo si existe), 6) ",(0,n.jsx)(o.strong,{children:"Continuous monitoring"})," (escanea im\xe1genes en Docker Hub autom\xe1ticamente, sin re-escanear manualmente). Trivy (Aqua, open-source) se enfoca en detectar CVEs y misconfigurations con escaneo r\xe1pido y bajo la l\xednea de comandos. Scout es una plataforma (con UI web en Docker Hub) que agrega remediaci\xf3n y pol\xedticas."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),': Docker Scout fue presentado en DockerCon 2022 como la respuesta de Docker a la creciente importancia de supply chain security. Est\xe1 incluido en Docker Pro/Team/Business subscriptions. Trivy es open-source, gratuito, y funciona offline (sin depender de SaaS). Scout usa los mismos datos de vulnerabilidad (NVD, distribuciones Linux) pero agrega la capa de "qu\xe9 hacer al respecto". La integraci\xf3n con Docker Hub permite que cada push a un repositorio active un escaneo autom\xe1tico y los resultados sean visibles en la UI. Para equipos que ya usan Docker Hub y tienen Docker subscription, Scout es conveniente. Para equipos que prefieren open-source o necesitan escaneo en CI offline, Trivy es la opci\xf3n.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"5-conectar-la-clase-menciona---cap-drop-all-c\xf3mo-se-relacionan-las-capabilities-con-los-user-namespaces-un-contenedor-que-corre-como-root-con-capabilities-restringidas-es-realmente-seguro",children:["5. [Conectar] La clase menciona ",(0,n.jsx)(o.code,{children:"--cap-drop ALL"}),". \xbfC\xf3mo se relacionan las capabilities con los user namespaces? \xbfUn contenedor que corre como root con capabilities restringidas es realmente seguro?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": Con ",(0,n.jsx)(o.code,{children:"--cap-drop ALL --cap-add NET_BIND_SERVICE"}),", el usuario root dentro del contenedor tiene su poder dr\xe1sticamente reducido: no puede montar filesystems, modificar el reloj del sistema, cargar m\xf3dulos de kernel, o hacer ptrace. PERO sigue siendo root (UID 0 dentro del contenedor): puede leer/escribir cualquier archivo con permisos de root del sistema de archivos del contenedor, bindear a puertos permitidos, y acceder a recursos del kernel que no requieren capabilities. Con user namespaces (",(0,n.jsx)(o.code,{children:"--userns-remap default"})," o el mapeo en daemon.json), el root del contenedor se mapea a un UID no privilegiado en el host (ej. UID 100000). Esto significa que incluso si root dentro del contenedor logra escapar (ej. explotando una vulnerabilidad del kernel), en el host es un usuario sin privilegios. La combinaci\xf3n es defensa en profundidad: capabilities reducen lo que root puede hacer dentro del contenedor, user namespaces protegen el host si el contenedor es comprometido."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n de kernel (man 7 user_namespaces, man 7 capabilities) explica esta interacci\xf3n. Las capabilities son efectivas DENTRO del user namespace. Un proceso con UID 0 en un user namespace tiene capacidades plenas DENTRO de ese namespace, pero en el namespace padre (host) su UID es 100000 (sin privilegios). Docker con ",(0,n.jsx)(o.code,{children:"--userns-remap"})," habilita user namespaces por defecto para todos los contenedores. Esto es configurable en ",(0,n.jsx)(o.code,{children:"/etc/docker/daemon.json"})," con ",(0,n.jsx)(o.code,{children:"userns-remap: default"})," y ",(0,n.jsx)(o.code,{children:"/etc/subuid"})," + ",(0,n.jsx)(o.code,{children:"/etc/subgid"}),". Es una de las features de seguridad m\xe1s efectivas y menos usadas (porque requiere configuraci\xf3n inicial y algunas operaciones como bind mounts de paths del host son m\xe1s complejas)."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsx)(o.h3,{id:"6-conectar-qu\xe9-es-exactamente-docker-content-trust-dct-y-c\xf3mo-se-relaciona-con-the-update-framework-tuf-y-notary-c\xf3mo-protege-contra-ataques-de-supply-chain",children:"6. [Conectar] \xbfQu\xe9 es exactamente Docker Content Trust (DCT) y c\xf3mo se relaciona con The Update Framework (TUF) y Notary? \xbfC\xf3mo protege contra ataques de supply chain?"}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": DCT (Docker Content Trust) usa Notary (proyecto CNCF) que implementa TUF (The Update Framework) para firmar y verificar im\xe1genes. Con DCT habilitado (",(0,n.jsx)(o.code,{children:"export DOCKER_CONTENT_TRUST=1"}),"), al hacer ",(0,n.jsx)(o.code,{children:"docker pull"}),': 1) Docker descarga el manifiesto de la imagen, 2) Contacta al servidor Notary asociado al registry para verificar la firma del tag, 3) Notary verifica la cadena de confianza TUF: root key \u2192 target key \u2192 tag signature, 4) Si la firma no coincide o no existe, Docker rechaza la imagen. Esto protege contra: ataques de "man in the middle" (modificaci\xf3n de la imagen en tr\xe1nsito), compromise del registry (un atacante reemplaza la imagen), y suplantaci\xf3n de identidad (imagen con tag ',(0,n.jsx)(o.code,{children:"official"})," pero firmada por un atacante). TUF agrega layers de seguridad: root key offline, timestamp key para prevenir replay attacks, y snapshot key para consistencia del repositorio."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": TUF fue desarrollado por Justin Cappos (NYU) y la comunidad de Python (PEP 458) para proteger PyPI. Notary (Docker Inc., donado a CNCF) implementa TUF para el ecosistema Docker. La jerarqu\xeda de claves en DCT: Root key (offline, usada solo para rotar otras claves), Repository key (firma los tags de un repositorio), Snapshot key (firma el snapshot del estado del repositorio), Timestamp key (firma el timestamp para prevenir replay). DCT est\xe1 siendo gradualmente reemplazado por Cosign/Sigstore (m\xe1s simple, keyless signing), pero el concepto de TUF sigue siendo relevante."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"7-conectar-c\xf3mo-funciona-docker-run---read-only-y-en-qu\xe9-casos-es-aplicable-c\xf3mo-manej\xe1s-directorios-que-necesitan-escritura-como-tmp-o-varrun",children:["7. [Conectar] \xbfC\xf3mo funciona ",(0,n.jsx)(o.code,{children:"docker run --read-only"})," y en qu\xe9 casos es aplicable? \xbfC\xf3mo manej\xe1s directorios que necesitan escritura (como ",(0,n.jsx)(o.code,{children:"/tmp"})," o ",(0,n.jsx)(o.code,{children:"/var/run"}),")?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": ",(0,n.jsx)(o.code,{children:"--read-only"})," monta el sistema de archivos ra\xedz del contenedor como read-only (a nivel de kernel, no se puede escribir en ninguna parte del filesystem de la imagen). Es aplicable para aplicaciones stateless que no necesitan escritura en disco (la mayor\xeda de los microservicios, APIs, workers). Para directorios que NECESITAN escritura, mont\xe1s tmpfs o vol\xfamenes writeables en paths espec\xedficos: ",(0,n.jsx)(o.code,{children:"--tmpfs /tmp:rw,noexec,nosuid,size=256M"}),", ",(0,n.jsx)(o.code,{children:"-v /var/run"}),", ",(0,n.jsx)(o.code,{children:"-v app-data:/data"}),'. Esto implementa el principio de "m\xednimo filesystem escribible": la aplicaci\xf3n solo puede escribir donde expl\xedcitamente le das permiso. Ventajas de seguridad: 1) un atacante no puede modificar binarios o configuraciones de la aplicaci\xf3n, 2) malware no puede persistirse (al reiniciar, el tmpfs est\xe1 limpio), 3) previene escritura accidental de logs o archivos que llenan la capa overlay.']}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": ",(0,n.jsx)(o.code,{children:"--read-only"})," configura el mount del root filesystem con ",(0,n.jsx)(o.code,{children:"ro"})," flag (en el spec de OCI: ",(0,n.jsx)(o.code,{children:"readonlyRootfs: true"}),"). Docker recomienda ",(0,n.jsx)(o.code,{children:"--read-only"})," en las Docker Security Best Practices. Para aplicaciones que escriben logs a archivos, la app debe configurarse para escribir a stdout/stderr (que Docker captura sin necesidad de filesystem). Para aplicaciones que generan archivos temporales (uploads), mont\xe1s un volumen persistente o tmpfs. En K8s, ",(0,n.jsx)(o.code,{children:"securityContext.readOnlyRootFilesystem: true"})," es el equivalente y es recomendado por el CIS K8s Benchmark."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsx)(o.h3,{id:"8-cuestionar-root-en-un-contenedor-es-root-en-el-host-es-esto-cierto-o-un-mito-qu\xe9-protecciones-existen-entre-root-del-contenedor-y-root-del-host",children:'8. [Cuestionar] "Root en un contenedor es root en el host". \xbfEs esto cierto o un mito? \xbfQu\xe9 protecciones existen entre root del contenedor y root del host?'}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": Es una simplificaci\xf3n peligrosa pero con algo de verdad. Por defecto (sin user namespaces), el UID 0 dentro del contenedor es el MISMO UID 0 en el host (el kernel no distingue). Sin embargo, las capabilities de ese root est\xe1n restringidas por Docker (por defecto, Docker dropea ~25 capabilities peligrosas). Adem\xe1s, seccomp bloquea syscalls peligrosas. Entonces: root del contenedor NO es id\xe9ntico a root del host (no puede hacer ",(0,n.jsx)(o.code,{children:"reboot"}),", ",(0,n.jsx)(o.code,{children:"mount"}),", ",(0,n.jsx)(o.code,{children:"kexec"}),'), pero sigue siendo UID 0 con m\xe1s de 10 capabilities permitidas, y si encuentra una vulnerabilidad del kernel o una capability no restringida, PUEDE escalar a root del host. La afirmaci\xf3n correcta es: "Root en un contenedor con configuraci\xf3n por defecto tiene menos privilegios que root en el host, pero sigue siendo peligroso y debe evitarse". Con user namespaces habilitados, root del contenedor se mapea a un usuario no privilegiado en el host, haciendo la afirmaci\xf3n falsa.']}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": Jessie Frazelle (ex-Docker) y Liz Rice (Isovalent) han dado charlas demostrando container breakouts. El CVE-2019-5736 (runc vulnerability) permiti\xf3 a un root de contenedor sobrescribir el binario runc en el host, escalando a root real. Los researchers de Aqua Security y Palo Alto Unit 42 han demostrado m\xfaltiples escapes. La defensa: 1) nunca correr como root en producci\xf3n (USER no-root), 2) ",(0,n.jsx)(o.code,{children:"--cap-drop ALL --cap-add"})," solo lo necesario, 3) ",(0,n.jsx)(o.code,{children:"--security-opt no-new-privileges"}),", 4) user namespaces, 5) seccomp profiles estrictos, 6) AppArmor/SELinux. Ninguna capa sola es suficiente."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"9-cuestionar-es-docker-run---privileged-alguna-vez-aceptable-en-producci\xf3n-qu\xe9-casos-de-uso-lo-justifican-y-c\xf3mo-mitig\xe1s-el-riesgo",children:["9. [Cuestionar] \xbfEs ",(0,n.jsx)(o.code,{children:"docker run --privileged"})," alguna vez aceptable en producci\xf3n? \xbfQu\xe9 casos de uso lo justifican y c\xf3mo mitig\xe1s el riesgo?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": ",(0,n.jsx)(o.code,{children:"--privileged"}),' es raramente aceptable en producci\xf3n. Casos que lo "justifican": 1) Docker-in-Docker (dind) para CI/CD runners (aunque ',(0,n.jsx)(o.code,{children:"sysbox"})," o ",(0,n.jsx)(o.code,{children:"rootless"})," son alternativas m\xe1s seguras), 2) Contenedores que necesitan acceso a hardware real (dispositivos USB, GPU), 3) Herramientas de monitoreo del kernel (eBPF-based, aunque ",(0,n.jsx)(o.code,{children:"CAP_BPF"})," es suficiente), 4) Contenedores de red avanzada (que necesitan manipular iptables, rutas). Mitigaciones si es inevitable: 1) Aislar en un namespace/user separado con user namespaces, 2) Aplicar seccomp profile restrictivo incluso al contenedor privileged, 3) Ejecutar como usuario no-root (paradojico pero posible: ",(0,n.jsx)(o.code,{children:"--privileged --user 1000"}),"), 4) Usar ",(0,n.jsx)(o.code,{children:"--security-opt"})," adicionales, 5) CORRER en un nodo dedicado y aislado del resto del cluster, 6) Usar herramientas como ",(0,n.jsx)(o.code,{children:"sysbox"}),' (Nestybox) que implementan contenedores "privileged" pero con user namespaces y aislamiento adicional.']}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n de Docker advierte que ",(0,n.jsx)(o.code,{children:"--privileged"})," es peligroso. Herramientas como dind se usan ampliamente en CI/CD (GitLab CI, Tekton) con ",(0,n.jsx)(o.code,{children:"--privileged"}),', pero la tendencia es reemplazarlo con rootless Docker o sysbox. Sysbox (Nestybox, ahora parte de Docker) implementa un "sys container" que puede ejecutar Docker interno sin ',(0,n.jsx)(o.code,{children:"--privileged"}),", usando user namespaces avanzados y capacidades espec\xedficas. Para 2025, la mayor\xeda de los casos de ",(0,n.jsx)(o.code,{children:"--privileged"})," tienen alternativas m\xe1s seguras."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsx)(o.h3,{id:"10-cuestionar-deben-las-organizaciones-adoptar-zero-trust-en-la-red-de-contenedores-mtls-networkpolicy-o-es-suficiente-con-firewalls-perimetrales-tradicionales",children:'10. [Cuestionar] \xbfDeben las organizaciones adoptar "zero trust" en la red de contenedores (mTLS, NetworkPolicy) o es suficiente con firewalls perimetrales tradicionales?'}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),': Zero trust es necesario en entornos de contenedores modernos porque el per\xedmetro tradicional desaparece: los contenedores son ef\xedmeros, las IPs cambian constantemente, y los servicios se comunican entre s\xed dentro del cluster (tr\xe1fico este-oeste) que nunca atraviesa el firewall perimetral. Un atacante que compromete un solo contenedor puede moverse lateralmente a otros servicios internos sin ser detectado por firewalls de borde. Zero trust con mTLS (Service Mesh como Istio/Linkerd/Cilium) + NetworkPolicy implementa: 1) Toda comunicaci\xf3n entre servicios es autenticada y cifrada (mTLS), 2) Solo se permite comunicaci\xf3n expl\xedcitamente declarada (NetworkPolicy deny-all + allow espec\xedfico), 3) La identidad del servicio (SPIFFE) es verificable criptogr\xe1ficamente, no basada en IP. Esto es necesario incluso en redes "internas" porque el insider threat es real.']}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),': El paper de Google "BeyondCorp" (2014) y el de Netflix sobre service mesh documentan la necesidad de zero trust. El CIS K8s Benchmark recomienda NetworkPolicy como control esencial. Incidentes reales (Capital One breach 2019, Tesla cryptojacking 2018) involucraron movimientos laterales dentro del cluster que firewalls perimetrales no detectaron. La implementaci\xf3n pr\xe1ctica: NetworkPolicy + mTLS con Istio/Linkerd/Cilium + runtime security con Falco.']})]})}function u(e={}){const{wrapper:o}={...(0,r.R)(),...e.components};return o?(0,n.jsx)(o,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,o,a){a.d(o,{R:()=>i,x:()=>c});var s=a(96540);const n={},r=s.createContext(n);function i(e){const o=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(o):{...o,...e}},[o,e])}function c(e){let o;return o=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:i(e.components),s.createElement(r.Provider,{value:o},e.children)}}}]);